        patron = LocalizedText("""Santo patrón de causas imposibles, enfermedades, heridas, problemas maritales, abusos y madres""", """Patron saint of impossible causes, sickness, wounds, marital problems, abuse, and mothers""", """Novena a Santa Rita - Causas Impossíveis"""),
        category = LocalizedText("""Novenas""", """Novenas""", """Novenas"""),
        description = LocalizedText("""Santa Rita de Casia fue esposa y madre, luego, después de que mataron a su esposo, fue monja. Reza esta novena por causas imposibles, problemas matrimoniales y abusos.""", """St Rita of Cascia was a wife and mother, then after her husband was killed, a nun. Pray this novena for impossible causes, marital problems, and abuse.""", """Santo padroeiro de causas impossíveis, doenças, feridas, problemas conjugais, abuso e mães"""),
